    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A physician receives a expensive gift (e.g., $500 watch) from a patient after a successful surgery. The most professional action is to:', '["Accept it as a token of appreciation", "Politely decline the gift to maintain professional boundaries and avoid the appearance of a conflict of interest", "Sell it and donate the money", "Wear it only when the patient visits"]', 1, 'Small, inexpensive gifts (like cookies or a card) are generally acceptable, but expensive gifts can create a sense of obligation or blur the lines of the professional relationship.'),
    (v_topic_id, 'A medical student is asked to introduce themselves as "Dr. Smith" to a patient. This is:', '["Standard practice for students", "Unethical and a violation of veracity, as it misrepresents the student''s training and role", "Fine if the resident is present", "A good way to gain confidence"]', 1, 'Students must always identify themselves as "medical students" to ensure the patient is accurately informed about who is providing their care.'),
    (v_topic_id, 'A physician notices their colleague smells of alcohol during a morning shift. The most appropriate first action is to:', '["Tell the colleague to go home and sleep it off", "Report the colleague immediately to the hospital''s physician health program or clinical leadership to protect patient safety", "Wait and see if they make a mistake", "Ask the nurses to watch them"]', 1, 'Patient safety is the absolute priority. Reporting an impaired colleague is a professional duty (Non-maleficence).'),
    (v_topic_id, 'A "Fiduciary" relationship means that:', '["The physician is always right", "The physician is legally and ethically bound to act in the best interest of the patient, prioritizing the patient''s needs over their own", "The patient must pay the bill immediately", "None of the above"]', 1, 'The patient-physician relationship is built on trust and the physician''s commitment to the patient''s welfare.'),
    (v_topic_id, 'Which of the following is a "Boundary Violation" in the patient-physician relationship?', '["Sharing a meal with a current patient at their home", "Entering into a romantic or sexual relationship with a current patient", "Borrowing money from a patient", "All of the above"]', 3, 'Maintaining clear professional boundaries is essential to protect the integrity of the relationship and prevent exploitation.'),
    (v_topic_id, 'A physician accidentally sticks themselves with a needle after using it on a patient. The patient refuses to be tested for HIV or Hepatitis. The physician:', '["Can force the patient to have the blood draw", "Must respect the patient''s refusal but can use previously drawn blood if state law allows, or follow post-exposure prophylaxis protocols", "Should yell at the patient", "None of the above"]', 1, 'Respect for autonomy continues even when it affects the provider. State laws vary on "exposure" testing, but the patient cannot be physically forced.'),
    (v_topic_id, 'Which term describes the process where a hospital reviews the clinical outcomes and complications of an individual physician to ensure they are meeting standards?', '["Morbidity and Mortality (M&M) conference", "Credentialing and Peer Review", "Root Cause Analysis", "Triage"]', 1, 'Peer review is a key part of maintaining professional quality and self-regulation in medicine.'),
    (v_topic_id, 'A physician is offered a "Speaking Fee" by a pharmaceutical company to talk about their new drug. To be ethical, the physician must:', '["Only use the company''s slides", "Disclose the conflict of interest to any audience and ensure the content is evidence-based and not just marketing", "Keep the payment a secret", "None of the above"]', 1, 'Transparency and objectivity are required in all interactions with industry.'),
    (v_topic_id, 'A "Handoff" or "Sign-out" is a high-risk period for medical errors. The best way to improve safety during a handoff is to:', '["Do it quickly via text", "Use a standardized, structured communication tool (e.g., I-PASS or SBAR) with an opportunity for questions", "Assume the next person knows the patient", "Only discuss the sickest patients"]', 1, 'Standardized communication reduces the risk of missing critical information during transitions of care.'),
    (v_topic_id, 'The "SBAR" communication tool stands for:', '["Security, Baseline, Analysis, Referral", "Situation, Background, Assessment, Recommendation", "Symptoms, Blood, Airway, Radiology", "None of the above"]', 1, 'SBAR is a widely used framework for concise and clear communication among healthcare professionals.'),
    (v_topic_id, 'A "Cultural Competence" (or Cultural Humility) approach in medicine involves:', '["Memorizing a list of stereotypes about different groups", "Recognizing and respecting a patient''s cultural beliefs and values and how they impact their health decisions", "Treating everyone exactly the same, ignoring their culture", "None of the above"]', 1, 'Respecting diversity is an application of the principle of respect for persons (Autonomy).'),
    (v_topic_id, 'An "Adverse Event" in a hospital is defined as:', '["A patient who complains about the food", "An injury caused by medical management rather than the underlying disease", "A patient who refuses a test", "None of the above"]', 1, 'Adverse events can be preventable or non-preventable.'),
    (v_topic_id, 'A "Malpractice" lawsuit for negligence requires the plaintiff to prove four things: Duty, Breach of Duty, Damages, and:', '["Intent to harm", "Causation (the breach caused the damages)", "A high bill", "None of the above"]', 1, 'Medical malpractice is a "tort" law issue, not a criminal one (unless there was gross/criminal negligence).'),
    (v_topic_id, 'The "Standard of Care" in a malpractice case is determined by:', '["The patient''s family", "What a ''reasonably competent'' physician in the same field would have done under similar circumstances", "The hospital board", "The local news"]', 1, 'Experts usually testify to establish what the standard of care is for a specific situation.'),
    (v_topic_id, 'A "Statute of Limitations" in medical malpractice refers to:', '["The maximum amount of money a patient can win", "The time limit within which a patient must file a lawsuit after the injury occurred or was discovered", "The number of witnesses allowed", "None of the above"]', 1, 'Statutes of limitations vary by state and type of claim.'),
    (v_topic_id, 'Which of the following is true regarding "Medical Errors"?', '["They are usually caused by a single incompetent individual", "They are often the result of multiple system failures (''Swiss Cheese Model'')", "They should be hidden to avoid lawsuits", "They only happen to bad doctors"]', 1, 'The Swiss Cheese Model explains how small, seemingly insignificant errors can align to cause a major disaster.'),
    (v_topic_id, '"Active Errors" occur at the "sharp end" of care. An example is:', '["A poorly designed computer system", "A physician picking up the wrong syringe and injecting it", "Understaffing in the pharmacy", "None of the above"]', 1, 'Active errors are the direct actions of the front-line staff.'),
    (v_topic_id, '"Latent Errors" occur at the "blunt end" of the system. An example is:', '["A surgeon making a mistake during a procedure", "A hospital policy that encourages long, exhausting shifts for residents", "A nurse giving the wrong dose", "None of the above"]', 1, 'Latent errors are the underlying organizational flaws that set the stage for active errors.'),
    (v_topic_id, 'A "Time-Out" before surgery is intended to prevent:', '["Wrong-site, wrong-procedure, or wrong-person surgery", "The surgeon being late", "Equipment failure", "The patient waking up"]', 0, 'The universal protocol (Time-Out) is a critical safety step involving the entire surgical team.'),
    (v_topic_id, '"Closed-Loop Communication" in an emergency (like a code) means:', '["The doctor tells everyone to be quiet", "The person receiving an order repeats it back to the sender, and the sender confirms it is correct", "The door is closed", "None of the above"]', 1, 'Closed-loop communication ensures that orders are heard and understood correctly under stress.'),
    (v_topic_id, 'A physician finds a way to "Work Around" a safety feature in the electronic health record because it is annoying. This is:', '["Efficiency", "A safety risk that should be reported and fixed at the system level", "A good idea", "None of the above"]', 1, 'Workarounds are often signs of a poorly designed system, but they bypass critical safeguards.'),
    (v_topic_id, 'Which of the following is a key element of "Informed Refusal"?', '["Explaining the benefits of the treatment", "Ensuring the patient understands the specific risks and consequences of *not* having the treatment", "Asking the family to sign the refusal form", "None of the above"]', 1, 'Refusing treatment requires the same level of information and capacity as consenting to it.'),
    (v_topic_id, 'A patient with a terminal illness is in the "Denial" phase of grief. The physician should:', '["Force them to face the truth immediately", "Acknowledge the denial as a normal coping mechanism while gently and repeatedly offering information as the patient is ready to hear it", "Stop all treatment", "None of the above"]', 1, 'Grief stages (Kübler-Ross: Denial, Anger, Bargaining, Depression, Acceptance) are not linear and require a compassionate, patient-centered approach.'),
    (v_topic_id, 'The "SPIKES" protocol is used for:', '["Treating an infection", "Breaking bad news", "Performing a physical exam", "Managing a hospital budget"]', 1, 'SPIKES: Setting, Perception, Invitation, Knowledge, Empathy, Strategy/Summary.'),
    (v_topic_id, 'When using the SPIKES protocol, the "Invitation" step involves:', '["Inviting the patient''s family to the meeting", "Asking the patient how much information they would like to hear about their diagnosis or prognosis", "Inviting the patient to stay for lunch", "None of the above"]', 1, 'Not all patients want to know every detail; "inviting" them to set the level of detail respects their autonomy.'),
    (v_topic_id, 'A patient is angry after a medical error occurred. The most professional response from the physician is to:', '["Defend their actions and blame the system", "Acknowledge the error, apologize sincerely, and explain what is being done to help the patient and prevent it from happening again", "Avoid the patient until they calm down", "Tell the patient to call their lawyer"]', 1, 'Disclosure and apology are now widely recognized as the most ethical and (often) the best risk-management strategy after an error.'),
    (v_topic_id, 'Which of the following is an example of "Non-abandonment"?', '["Leaving a patient''s bedside during an emergency", "Providing a list of alternative providers and 30 days of medications when ending a patient relationship", "Refusing to see a patient who can''t pay", "None of the above"]', 1, 'Abandonment is the abrupt termination of care without ensuring the patient has a way to continue treatment.'),
    (v_topic_id, 'A physician is "Burned Out" and finds it difficult to feel empathy for their patients. This is a sign of:', '["High professionalism", "Depersonalization (a core component of burnout)", "Being a ''tough'' doctor", "None of the above"]', 1, 'Burnout (Emotional Exhaustion, Depersonalization, and Low Personal Accomplishment) is a major threat to both physician well-being and patient safety.'),
    (v_topic_id, 'The "Social Contract" in medicine refers to:', '["The agreement between a doctor and their lawyer", "The societal expectation that physicians will put the interests of their patients and the public above their own in exchange for autonomy and status", "The hospital''s employment contract", "None of the above"]', 1, 'Professionalism is the way physicians fulfill their end of the social contract.'),
    (v_topic_id, 'A physician refuses to treat a patient because the patient''s insurance plan pays very low rates. Is this legal?', '["Yes, for new patients, as long as the refusal is not based on discriminatory factors", "No, it is always illegal", "Only if the patient is a minor", "Only in an emergency"]', 0, 'Physicians generally have the right to choose which insurance plans they accept, but once a relationship is established, they must follow proper termination procedures.'),
    (v_topic_id, 'Which of the following is true about "Self-Care" for physicians?', '["It is a sign of weakness", "It is an ethical and professional necessity to ensure the physician is capable of providing safe and effective care", "It is only for residents", "None of the above"]', 1, 'A physician who does not care for themselves cannot effectively care for others.'),
    (v_topic_id, 'A 15-year-old girl wants to start birth control. She asks the doctor not to tell her mother. The doctor should:', '["Call the mother immediately", "Respect the minor''s confidentiality (in most states)", "Tell the girl she is too young", "None of the above"]', 1, 'Confidentiality for sensitive services like contraception is a legal right for minors in most jurisdictions.'),
    (v_topic_id, 'What is "Clinical Equipoise"?', '["The doctor being perfectly balanced on one foot", "Genuine uncertainty within the expert medical community about which of two or more treatments is superior", "Having enough doctors and nurses on a shift", "None of the above"]', 1, 'Equipoise is a requirement for the ethical conduct of a randomized controlled trial.'),
    (v_topic_id, 'A "Conflict of Interest" occurs when:', '["Two doctors disagree", "A physician''s primary obligation (the patient''s welfare) is potentially compromised by a secondary interest (like financial gain or research prestige)", "The patient is angry", "None of the above"]', 1, 'COIs must be disclosed and managed to protect the integrity of medical care.'),
    (v_topic_id, 'Which of the following is an example of "Physician Impairment"?', '["A physician with a broken arm who can''t do surgery", "A physician with an untreated substance use disorder that compromises their judgment or skill", "A physician who is tired after a long shift", "None of the above"]', 1, 'Impairment refers to a condition that makes it unsafe for the physician to practice.'),
    (v_topic_id, 'A patient is "Drug-Seeking" and demands high-dose opioids for a minor injury. The physician refuses. The physician is prioritizing:', '["Autonomy over Non-maleficence", "Non-maleficence and Justice (stewardship) over a patient''s ''autonomy'' to demand harmful/non-indicated care", "Justice over Veracity", "None of the above"]', 1, 'Patients do not have the right to demand care that the physician deems harmful or inappropriate.'),
    (v_topic_id, 'The "Hidden Curriculum" in medical education refers to:', '["The classes that are held at night", "The unwritten, unofficial values and behaviors that students learn from observing their superiors, which can sometimes contradict the formal ethics curriculum", "The names of the diseases", "None of the above"]', 1, 'The hidden curriculum can profoundly shape a student''s professional identity.'),
    (v_topic_id, 'A "Medical Error of Omission" is:', '["Doing the wrong thing", "Failing to do the right thing (e.g., forgetting to prescribe a necessary prophylactic antibiotic)", "Making a typo", "None of the above"]', 1, 'Omission (not doing something) is just as dangerous as commission (doing the wrong thing).'),
    (v_topic_id, 'The "Five Rights" of medication administration are Right Patient, Right Drug, Right Dose, Right Route, and:', '["Right Doctor", "Right Time", "Right Price", "Right Color"]', 1, 'The 5 rights are a standard safety check for nurses and doctors.'),
    (v_topic_id, 'Which of the following is true about "Placebo-Controlled Trials" when an effective treatment already exists?', '["They are always ethical", "They are generally considered unethical if they expose the placebo group to a high risk of serious harm, as the new drug should be compared to the ''current standard of care", "They are required by the FDA", "None of the above"]', 1, 'Comparing a new drug to an existing, effective one is called an "active-controlled" trial.'),
    (v_topic_id, 'A physician provides "Palliative Sedation" to a terminal patient in severe distress. The goal is to:', '["Kill the patient", "Induce a state of decreased consciousness to relieve intractable suffering at the end of life", "Save money on medications", "None of the above"]', 1, 'Palliative sedation is a last-resort measure for "refractory" symptoms.'),
    (v_topic_id, 'A "Sentinel Event" requires the hospital to notify:', '["The local newspaper", "The Joint Commission (for accredited hospitals)", "The patient''s family members in other states", "None of the above"]', 1, 'Reporting to the Joint Commission is part of the accreditation process.'),
    (v_topic_id, 'Which of the following describes "Standardization" as a safety strategy?', '["Treating every patient with the same dose regardless of weight", "Creating uniform processes (e.g., a standardized checklist for central line insertion) to reduce variation and error", "Using only one brand of hospital bed", "None of the above"]', 1, 'Standardization is a core principle of human factors engineering for safety.'),
    (v_topic_id, 'A "Culture of Safety" in a hospital is characterized by:', '["Zero errors ever", "Shared values and behaviors where safety is prioritized, reporting is encouraged, and learning occurs from mistakes", "No one ever being fired", "None of the above"]', 1, 'A safety culture is a collective commitment to protecting patients.'),
    (v_topic_id, 'If a patient has "Locked-In Syndrome" (fully aware but paralyzed except for eye movements), their autonomy should be respected by:', '["Making all decisions for them", "Using specialized communication tools (like eye-tracking) to allow the patient to express their own choices", "Asking the family only", "None of the above"]', 1, 'As long as the patient can communicate in any way, they should be the primary decision-maker.'),
    (v_topic_id, 'Which of the following is true regarding "Gifts from Industry" (e.g., drug reps) to physicians according to modern guidelines?', '["Any gift is fine as long as it''s useful", "Physicians should generally not accept gifts from industry, even small ones like pens or pads, as they can subtly influence prescribing behavior", "Gifts under $1000 are okay", "None of the above"]', 1, 'Most medical societies and hospitals now ban or strictly limit industry gifts.'),
    (v_topic_id, 'The "Sunshine Act" (part of the Affordable Care Act) requires:', '["Doctors to work more in the sun", "Manufacturers of drugs and medical devices to publicly report payments and gifts made to physicians and teaching hospitals", "All hospitals to have windows", "None of the above"]', 1, 'The Open Payments database allows the public to see financial relationships between doctors and industry.'),
    (v_topic_id, 'A physician is "Moonlighting" (working a second job) and is severely sleep-deprived. This is a violation of:', '["Justice", "Professional Responsibility to ensure they are fit for duty (Patient Safety)", "Autonomy", "None of the above"]', 1, 'Fatigue is a significant risk factor for medical error.'),
    (v_topic_id, 'A patient is diagnosed with a terminal illness. They ask: "Will I suffer?" The most professional and empathetic response is:', '["Yes, probably", "We will do everything possible to ensure you are comfortable and manage your pain and other symptoms aggressively", "Don''t worry about that now", "None of the above"]', 1, 'Validation and a commitment to comfort are key in palliative care.'),
    (v_topic_id, 'The final pearl of medical ethics: When in doubt, the most important question to ask is:', '["What is the most profitable course of action?", "What would a ''reasonably competent'' physician do to act in this specific patient''s best interest while respecting their rights?", "What is the fastest way to finish?", "What does the boss want?"]', 1, 'The core of medical ethics is the patient-centered focus on beneficence and respect.');
